/* CalPay transaction table */
.calpay-table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    font-size: 14px;
}

.calpay-table thead th {
    background-color: #2c3e50;
    color: #ffffff;
    padding: 10px;
    text-align: left;
    border: 1px solid #ddd;
}

.calpay-table tbody td {
    padding: 10px;
    border: 1px solid #ddd;
    vertical-align: top;
}

/* Zebra striping */
.calpay-table tbody tr:nth-child(odd) {
    background-color: #f9f9f9;
}

.calpay-table tbody tr:nth-child(even) {
    background-color: #ffffff;
}

/* Hover effect */
.calpay-table tbody tr:hover {
    background-color: #e8f4ff;
}

/* Amount columns */
.calpay-table td.amount {
    text-align: right;
    white-space: nowrap;
}

/* Smaller product details */
.calpay-table td.product {
    font-size: 13px;
}

.calpay-table tbody tr.failed-transaction {
    color: red;
}

.calpay-table tbody tr.failed-transaction:hover {
    background-color: #ffe6e6;
}

